MOCK_SUMMARIES = ["客人阿岩要做一份轻方案。", "客人阿岩要做轻量海报,主要用手机,标题不宜长。", "客人阿岩要做轻量海报,预算三百元以内。", "客人阿岩要做轻量海报,预算三百元,方案加入「山」字。", "客人阿岩要做轻量海报,移动端查看,预算三百元,加入「山」字,配深色边框。"]
SCRIPT = ["我叫阿岩,想做一份轻量海报。", "我主要用手机查看,标题别太长。", "预算三百元以内。", "海报加入一个「山」字。", "搭配一个深色边框。"]

