                      base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
                      api_key=os.environ["OPENAI_API_KEY"], temperature=0.3)


def get_summary_model():
    """摘要专用模型:每轮 save_context 都会调它做一次滚动压缩,温度调低求稳。"""
    if os.environ.get("MOCK_LLM"):
        return FakeListChatModel(responses=MOCK_SUMMARIES)
    return ChatOpenAI(model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"),
                      base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
                      api_key=os.environ["OPENAI_API_KEY"], temperature=0.2)


def make_memory(backend: str):
    """记忆后端工厂:三种策略到齐——buffer 流水账 / window 滑窗 / summary 滚动摘要。"""
    if backend == "buffer":
        return InMemoryChatMessageHistory()
    if backend == "window":
        return InMemoryChatMessageHistory()
    if backend == "summary":
        return InMemoryChatMessageHistory()
    raise ValueError(f"未知记忆后端: {backend}")


def count_tokens(messages) -> int:
    """用 cl100k_base 估算一组消息的 token 数(每条 +4 结构开销);离线兜底按字符近似。"""
    if ENCODING is not None:
        return sum(len(ENCODING.encode(m.content)) + 4 for m in messages)
    return sum(len(m.content) + 4 for m in messages)


def run_dialogue(advisor, script):
    """把同一份剧本灌给顾问,返回每轮过后记忆账本的 token 数列表。"""
    growth = []
    for line in script:
        advisor.chat(line)
        growth.append(count_tokens(advisor.memory.messages))
    return growth


class ForgeAdvisor:
    """黑糖资料室接待顾问:带着一本记忆账本接待咨询者。"""

    def __init__(self, model, memory=None, backend="buffer"):
        self.model = model
        self.backend = backend
        self.memory = memory or make_memory("buffer")

    def chat(self, user_input: str) -> str:
        """一轮接待:翻账 → 连账带话发给模型 → 把问答记回账本。"""
        history = self.memory.messages
        reply = self.model.invoke([*history, HumanMessage(content=user_input)]).content
        self.memory.add_user_message(user_input)
        self.memory.add_ai_message(reply)
        if self.backend == "window":
            self.memory.messages = self.memory.messages[-4:]
        elif self.backend == "summary":
            # 摘要是应用策略：用独立模型将旧上下文压成一条 AIMessage。
            summary = get_summary_model().invoke(
                "把以下对话压缩为不超过 80 字的事实摘要：\n" +
                "\n".join(message.content for message in self.memory.messages)
            ).content
            self.memory.messages = [AIMessage(content=summary)]
        return reply


def compare_backends(script):
    """三方对照:同剧本、同模型,唯一变量是记忆后端;summary 额外摊开摘要原文。"""
    print(f"剧本共 {len(script)} 轮,Window 后端 k=2\n")
    for backend in ("buffer", "window", "summary"):
        advisor = ForgeAdvisor(get_chat_model(MOCK_REPLIES), make_memory(backend), backend=backend)
        print(f"  后端 {backend:>7}: 逐轮 token -> {run_dialogue(advisor, script)}")
        if backend == "summary":
            # 摘要以 SystemMessage 形式留在记忆里,是模型的「背景设定」
            summary_text = advisor.memory.messages[0].content
            print(f"    摘要原文: {summary_text}")
            print(f"    「阿岩」是否幸存: {'是' if '阿岩' in summary_text else '否'}")
    print("\n读图: summary 与 window 都有平台期,但摘要保住了第 1 轮的姓名;")
    print("      代价是每轮多一次摘要 LLM 调用,且压缩有损,细节可能悄悄消失。")


def main() -> None:
    # 联网演示只需两轮即可比较三种策略，避免把同一个教学点变成 15 次 API 调用。
    # MOCK 仍保留完整五轮剧本，方便离线观察更长对话的压缩过程。
    compare_backends(SCRIPT if os.environ.get("MOCK_LLM") else SCRIPT[:2])


if __name__ == "__main__":
    main()

"""黑糖资料室 · 对话记忆策略 · s5：用 LangChain 完成可验证的学习任务。"""
import json
import os
import sys
import tiktoken
from langchain_core.chat_history import InMemoryChatMessageHistory
from langchain_core.language_models.fake_chat_models import FakeListChatModel
from langchain_core.messages import HumanMessage, messages_from_dict, messages_to_dict
from langchain_openai import ChatOpenAI

if not os.environ.get("OPENAI_API_KEY") and not os.environ.get("MOCK_LLM"):
    print("[提示词工作台] 未检测到 OPENAI_API_KEY。\n请先在右上角 AI 配置填入 DeepSeek API Key,然后重新运行。")
    sys.exit(0)

MEMORY_FILE = "forge_memory.json"
MOCK_REPLIES = ["幸会,阿岩!轻量海报便于移动端查看。", "移动端海报,标题会相应缩短。", "三百元以内,没问题。", "加入「山」字,好立意。", "深色边框,沉稳。", "下周五前交付,记下了。"]
SCRIPT = ["我叫阿岩,想做一份轻量海报。", "我主要用手机查看,标题别太长。", "预算三百元以内。", "海报加入一个「山」字。", "搭配一个深色边框。", "下周五前要交付。"]

try:
    ENCODING = tiktoken.get_encoding("cl100k_base")
except Exception:
    ENCODING = None


def get_chat_model(responses):
    """MOCK_LLM 时返回循环播放固定回复的假模型;否则返回指向 DeepSeek 的 ChatOpenAI。"""
    if os.environ.get("MOCK_LLM"):
        return FakeListChatModel(responses=responses)
    return ChatOpenAI(model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"),
                      base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
                      api_key=os.environ["OPENAI_API_KEY"], temperature=0.3)


def make_memory(backend: str):
    """记忆后端工厂:生产版只保留 buffer(配合上限控制),实验后端已拆除。"""
    if backend != "buffer":
        raise ValueError(f"生产版只保留 buffer 后端,收到: {backend}")
    return InMemoryChatMessageHistory()


def count_tokens(messages) -> int:
    """用 cl100k_base 估算一组消息的 token 数(每条 +4 结构开销);离线兜底按字符近似。"""
    if ENCODING is not None:
        return sum(len(ENCODING.encode(m.content)) + 4 for m in messages)
    return sum(len(m.content) + 4 for m in messages)


class ForgeAdvisor:
    def __init__(self, model, memory=None, backend="buffer"):
        self.model = model
        self.backend = backend
        self.memory = memory or make_memory(backend)

    def chat(self, user_input: str) -> str:
        """一轮接待:翻账 → 连账带话发给模型 → 把问答记回账本。"""
        history = self.memory.messages
        reply = self.model.invoke([*history, HumanMessage(content=user_input)]).content
        self.memory.add_user_message(user_input)
        self.memory.add_ai_message(reply)
        return reply

    def enforce_budget(self, max_tokens: int) -> int:
        """token 上限控制:超预算时成对淘汰最早的一问一答,返回淘汰条数。"""
        msgs = self.memory.messages
        removed = 0
        while len(msgs) > 2 and count_tokens(msgs) > max_tokens:
            del msgs[0:2]  # 成对删:孤儿消息会破坏 Human/AI 交替,有些 API 拒绝错乱序列
            removed += 2
        return removed

    def export_state(self) -> dict:
        """导出可序列化的记忆状态:messages_to_dict 给每条消息打上类型标签。"""
        return {"backend": self.backend,
                "messages": messages_to_dict(self.memory.messages)}

    def save(self, path: str = MEMORY_FILE) -> None:
        """记忆落盘:ensure_ascii=False 让中文以原文写入,账本保持人可读。"""
        with open(path, "w", encoding="utf-8") as f:
            json.dump(self.export_state(), f, ensure_ascii=False, indent=2)

    @classmethod
    def load(cls, model, path: str = MEMORY_FILE) -> "ForgeAdvisor":
        """从 JSON 恢复:重建同后端记忆,把消息逐条回放进新账本。"""
        with open(path, encoding="utf-8") as f:
            state = json.load(f)
        advisor = cls(model, make_memory(state["backend"]), backend=state["backend"])
        advisor.memory.add_messages(messages_from_dict(state["messages"]))
        return advisor

    def show_memory(self) -> None:
        """把账本摊开:逐条打印记忆里的消息及其类型。"""
        msgs = self.memory.messages
        print(f"== 记忆账本(共 {len(msgs)} 条) ==")
        for m in msgs:
            print(f"  [{type(m).__name__}] {m.content}")


def main() -> None:
    """完整流程:接待 → 瘦身 → 落盘 → 模拟重启 → 恢复验证。"""
    advisor = ForgeAdvisor(get_chat_model(MOCK_REPLIES))
    for line in SCRIPT:
        advisor.chat(line)
    before = count_tokens(advisor.memory.messages)
    removed = advisor.enforce_budget(max_tokens=120)
    print(f"token 预算 120: 瘦身前 {before} → 淘汰 {removed} 条 → 现存 {count_tokens(advisor.memory.messages)}")
    advisor.save()
    print(f"\n记忆已落盘 {MEMORY_FILE}(前 120 字节):")
    with open(MEMORY_FILE, encoding="utf-8") as f:
        print(f.read(120) + " ...")
    restored = ForgeAdvisor.load(get_chat_model(MOCK_REPLIES))
    print("\n模拟重启后恢复账本:")
    restored.show_memory()


if __name__ == "__main__":
    main()

"""黑糖资料室 · 项目咨询路由 · s2：用 LangChain 完成可验证的学习任务。"""
import os
import sys

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.language_models.fake_chat_models import FakeListChatModel
from langchain_core.output_parsers import StrOutputParser
from langchain_core.prompts import ChatPromptTemplate
from langchain_core.runnables import RunnableBranch, RunnablePassthrough
from langchain_openai import ChatOpenAI

MOCK_LLM = os.environ.get("MOCK_LLM") == "1"

# 无 Key 且未开 MOCK 时给出引导并优雅退出
if not MOCK_LLM and not os.environ.get("OPENAI_API_KEY"):
    print("[提示词工作台] 未检测到 OPENAI_API_KEY。")
    print("请先在右上角 AI 配置填入 DeepSeek API Key,然后重新运行。")
    sys.exit(0)

INTENT_OPTIONS = ("forge", "inscribe", "appraise", "chat")


def build_llm(mock_replies=None) -> BaseChatModel:
    """模型工厂:MOCK 时返回按剧本作答的假模型,否则接 DeepSeek。"""
    if MOCK_LLM:
        return FakeListChatModel(responses=mock_replies or ["chat"])
    return ChatOpenAI(
        model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"),
        base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
        api_key=os.environ["OPENAI_API_KEY"],
        temperature=0,
    )


def build_classifier_chain():
    """意图分类链(s1 的件):出口是原始判定文本。"""
    prompt = ChatPromptTemplate.from_messages([
        ("system", "你是提示词工作台的接待。判断客人来意,只回答一个词:"
                   "forge(内容制作)、inscribe(撰写文案)、appraise(质量评审)、chat(闲聊)。"),
        ("human", "{request}"),
    ])
    return prompt | build_llm(["forge", "inscribe", "appraise", "chat"]) | StrOutputParser()


def normalize_intent(raw: str) -> str:
    """清洗模型输出:包含即命中,不中归 chat。"""
    text = raw.strip().lower()
    for intent in INTENT_OPTIONS:
        if intent in text:
            return intent
    return "chat"


def build_forge_chain():
    """制作组:散文答复制作方案。"""
    prompt = ChatPromptTemplate.from_messages([("system", "你是内容策划助手,三句话内给出内容制作方案。"), ("human", "{request}")])
    return prompt | build_llm(["建议以冷色调素材为基础,补充标题层级与留白,再完成版式检查。"]) | StrOutputParser()


def build_inscribe_chain():
    """文案组:为内容方案撰写文案。"""
    prompt = ChatPromptTemplate.from_messages([("system", "你是文案师,题一句四言或七言文案。"), ("human", "{request}")])
    return prompt | build_llm(["让创意被看见,今日把示君。"]) | StrOutputParser()


def build_chat_chain():
    """咨询台:闲聊兜底,也是路由器的默认分支。"""
    prompt = ChatPromptTemplate.from_messages([("system", "你是提示词工作台掌柜,陪客人闲聊,谈吐风趣。"), ("human", "{request}")])
    return prompt | build_llm(["坐,处理器上正温着茶,慢慢聊。"]) | StrOutputParser()


def build_router():
    """路由器:assign 先给字典追加 intent 字段,RunnableBranch 再按序分流。"""
    # 判定 + 清洗焊成一道工序:函数接在 | 后面会被自动包装成 RunnableLambda
    classify = build_classifier_chain() | normalize_intent
    return RunnablePassthrough.assign(intent=classify) | RunnableBranch(
        (lambda x: x["intent"] == "forge", build_forge_chain()),
        (lambda x: x["intent"] == "inscribe", build_inscribe_chain()),
        build_chat_chain(),  # 默认分支:其余来意(含 appraise)一律奉茶,必须存在
    )


def main() -> None:
    """四位咨询者轮番上门,观察分流结果。"""
    router = build_router()
    guests = ["我要制作一份活动主视觉", "为这份方案写一句短文案", "帮我鉴赏这份旧版设计", "今天天气如何"]
    print("== 提示词工作台 · 三路分流 ==")
    for g in guests:
        reply = router.invoke({"request": g})
        print(f"客人:「{g}」\n  接待:{reply}")


if __name__ == "__main__":
    main()

"""黑糖资料室 · 项目咨询路由 · s4：用 LangChain 完成可验证的学习任务。"""
import os
import sys

from pydantic import BaseModel, Field
from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.language_models.fake_chat_models import FakeListChatModel
from langchain_core.output_parsers import PydanticOutputParser, StrOutputParser
from langchain_core.prompts import ChatPromptTemplate
from langchain_core.runnables import RunnableBranch, RunnablePassthrough
from langchain_openai import ChatOpenAI

MOCK_LLM = os.environ.get("MOCK_LLM") == "1"

# 无 Key 且未开 MOCK 时给出引导并优雅退出
if not MOCK_LLM and not os.environ.get("OPENAI_API_KEY"):
    print("[提示词工作台] 未检测到 OPENAI_API_KEY。")
    print("请先在右上角 AI 配置填入 DeepSeek API Key,然后重新运行。")
    sys.exit(0)

INTENT_OPTIONS = ("forge", "inscribe", "appraise", "chat")
MOCK_SWORD_JSON = '{"name": "晨光", "material": "冷色调素材", "sharpness": 92, "inscription": "让创意被看见"}'


class SwordOrder(BaseModel):
    """制作单(t12 的数据契约):制作组的硬出口。"""

    name: str = Field(description="方案名称,两到四个汉字")
    material: str = Field(description="主材,如 冷色调图片/品牌字体/活动图标")
    sharpness: int = Field(ge=1, le=100, description="质量评分,1-100")
    inscription: str = Field(description="方案文案,不超过十二字")


parser = PydanticOutputParser(pydantic_object=SwordOrder)


def build_llm(mock_replies=None) -> BaseChatModel:
    """模型工厂:MOCK 时返回按剧本作答的假模型,否则接 DeepSeek。"""
    if MOCK_LLM:
        return FakeListChatModel(responses=mock_replies or ["chat"])
    return ChatOpenAI(
        model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"),
        base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
        api_key=os.environ["OPENAI_API_KEY"],
        temperature=0,
    )


def build_classifier_chain():
    """意图分类链:本步剧本判出 制作 → 文案 → 制作。"""
    prompt = ChatPromptTemplate.from_messages([
        ("system", "你是提示词工作台的接待。判断客人来意,只回答一个词:"
                   "forge(内容制作)、inscribe(撰写文案)、appraise(质量评审)、chat(闲聊)。"),
        ("human", "{request}"),
    ])
    return prompt | build_llm(["forge", "inscribe", "forge"]) | StrOutputParser()


def normalize_intent(raw: str) -> str:
    text = raw.strip().lower()
    for intent in INTENT_OPTIONS:
        if intent in text:
            return intent
    return "chat"


def build_structured_forge_chain():
    """制作组主链:产出 SwordOrder;JSON 不合格会抛 OutputParserException。"""
    prompt = ChatPromptTemplate.from_messages([
        ("system", "你是内容策划助手,按契约输出内容方案单 JSON。"),
        ("human", "客人需求:{request}\n{format_instructions}"),
    ]).partial(format_instructions=parser.get_format_instructions())
    # MOCK 剧本:第一流程 JSON 残缺(逼出降级),第二流程合格(展示恢复)
    return prompt | build_llm(['{"name": "晨光", "material": "冷色调素材", "sha', MOCK_SWORD_JSON]) | parser


def build_fallback_forge_chain():
    """制作组副链:不要契约只要人话,故障面更小,兜底用。"""
    prompt = ChatPromptTemplate.from_messages([
        ("system", "你是内容策划助手,用三句散文给出内容制作建议。"),
        ("human", "{request}"),  # 输入变量必须与主链一致,否则降级时再炸一次
    ])
    return prompt | build_llm(["[降级] 模型服务繁忙,先使用品牌字体完成基础版式,稍后再补充细节。"]) | StrOutputParser()


def build_forge_chain():
    """主链挂副链:主链抛异常时自动降级,咨询者绝不空手而归。"""
    # with_fallbacks 的参数是 Runnable 的【列表】,按序尝试;默认捕获所有 Exception
    return build_structured_forge_chain().with_fallbacks([build_fallback_forge_chain()])


def build_inscribe_chain():
    """文案组:为内容方案撰写文案。"""
    prompt = ChatPromptTemplate.from_messages([("system", "你是文案师,题一句四言或七言文案。"), ("human", "{request}")])
    return prompt | build_llm(["让创意被看见,今日把示君。"]) | StrOutputParser()


def build_router():
    """路由器照旧:挂了降级的制作组链对上游完全透明。"""
    classify = build_classifier_chain() | normalize_intent
    return RunnablePassthrough.assign(intent=classify) | RunnableBranch(
        (lambda x: x["intent"] == "forge", build_forge_chain()),
        (lambda x: x["intent"] == "inscribe", build_inscribe_chain()),
        build_inscribe_chain(),  # 默认分支
    )


def main() -> None:
    """两次制作:第一流程降级为散文,第二流程恢复正常出制作单。"""
    router = build_router()
    guests = ["我要制作一份活动主视觉", "为这份方案写一句短文案", "再制作一份更好的"]
    print("== 提示词工作台 · 备用链演练 ==")
    for g in guests:
        result = router.invoke({"request": g})
        if isinstance(result, SwordOrder):
            print(f"「{g}」→ 主链出货 · 内容方案单:{result.name}|质量{result.sharpness}")
        else:  # 副链散文自带 [降级] 标记:主链失手,备用流程顶上
            print(f"「{g}」→ {result}")


if __name__ == "__main__":
    main()

"""黑糖资料室 · 第一步:开卷——把资料装进 Document"""
from dataclasses import dataclass, field
from pathlib import Path

# 内置语料:黑糖资料室的第一篇资料库(真实项目中它们原本就在磁盘上)
CORPUS = {
    "基础阶段总纲.txt": """基础阶段总纲

基础阶段者,工程实践之基石也。写入缓存区,意守入口条件,百日方可基础阶段。
初入门者每日每日早间数据清洗,采东方原始数据纳入数据池,切忌心浮气躁。

基础阶段有三境:一曰加载,二曰清洗,三曰索引。
加载期以通处理轮次为要;清洗期气化为液,存于缓存区;索引期液聚成丹,可窥进阶阶段完整路线。

常见走火之症有二:一曰字段错位,当即刻停功,以温水沐足;二曰上下文丢失,当静坐三日,只饮基础数据。
凡阁中成员须日日诵读此纲,不可懈怠。""",
}
LIB_DIR = Path("cangjingge")


def shelve_books(corpus: dict, lib_dir: Path) -> None:
    """把内置语料写入磁盘,模拟真实的黑糖资料室书库。"""
    lib_dir.mkdir(exist_ok=True)
    for name, content in corpus.items():
        (lib_dir / name).write_text(content, encoding="utf-8")  # 显式 UTF-8


@dataclass
class Document:
    """RAG 的最小流通单位:一段文本 + 它的出身证明(元数据)。"""

    page_content: str
    metadata: dict = field(default_factory=dict)  # 可变默认值必须用 factory

