import zlib

import numpy as np

CHUNK_SIZE = 60
CHUNK_OVERLAP = 15
EMBED_DIM = 512  # 哈希向量的维度
TOP_K = 3

# 黑糖资料室参考资料总目(第 1 步成果,原样保留)
DOCUMENTS = [
    {
        "doc_id": "yjj",
