    print("dispatch 计算:", dispatch("calculate", expression="1024 / 8"))
    print("dispatch 统计:", dispatch("count_text", text="社团工具箱真好玩"))
    print("dispatch 未知工具:", dispatch("fly_to_moon"))
    print("dispatch 缺参数:", dispatch("convert_case"))


