from langchain_core.tools import StructuredTool, ToolException

def handler(exc: ToolException) -> str:
    return f"[工具失败] {exc}"   # callable 形式可定制文案

tool = StructuredTool.from_function(
    func=refine_calc, name="refine_calc",
    description="...", args_schema=RefineInput,
    handle_tool_error=handler,  # 只兜 ToolException!
)
