steps.solutionCode:
"""Agent 运行时底座 · s2:Step 抽象——动作也要有生命周期

s1 的循环把「执行」揉进了一个函数,动作一多就难以扩展。
本步引入 Step 抽象:每个动作都过 prepare → execute → finish
三阶段,并发出结构化事件,由 Harness 统一调度、记录与回放。
"""
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass


class AgentStatus:
    """Agent 生命周期状态机。"""

    IDLE = "idle"
    RUNNING = "running"
    DONE = "done"
    ERROR = "error"


def get_time() -> str:
    """返回当前时间段。"""
    hour = time.localtime().tm_hour
    labels = ["深夜", "凌晨", "凌晨", "清晨", "早晨", "上午", "中午", "下午", "下午", "傍晚", "夜间", "深夜"]
    return f"当前时间段:{labels[hour % 12]}"


def list_meridians() -> str:
    """列出工作流主要阶段。"""
    return "工作流阶段:接收请求、选择工具、执行工具、汇总答复"


TOOLS = {"get_time": get_time, "list_meridians": list_meridians}


def run_tool(name: str) -> str:
    """工具分发器:按名字找到组件并执行。"""
    if name not in TOOLS:
        return f"[未知工具] {name}"
    return TOOLS[name]()


@dataclass
class Event:
    """一次生命周期事件:阶段、步骤名、附加细节。"""

    phase: str
    step: str
    detail: str = ""


class Step(ABC):
    """动作的抽象基类:每个动作都过 prepare / execute / finish 三段。"""

    def __init__(self, name: str):
        self.name = name

    @abstractmethod
    def prepare(self, ctx: dict) -> None:
        """执行前的准备:校验参数、检查前置条件。"""

    @abstractmethod
    def execute(self, ctx: dict) -> str:
        """真正干活:调用工具或直接作答,返回文本结果。"""

    @abstractmethod
    def finish(self, ctx: dict) -> None:
        """执行后的收尾:清理、记录副作用、更新状态。"""


class ToolStep(Step):
    """调用工具注册表中某个工具的步骤。"""

    def __init__(self, name: str, tool: str):
        super().__init__(name)
        self.tool = tool

    def prepare(self, ctx: dict) -> None:
        """校验工具确实存在,不存在就在进入 execute 前报错。"""
        if self.tool not in TOOLS:
            raise KeyError(f"工具库中没有 {self.tool} 这件工具")

    def execute(self, ctx: dict) -> str:
        result = run_tool(self.tool)
        ctx["actions"].append(self.tool)
        return result

    def finish(self, ctx: dict) -> None:
        ctx["messages"].append({"role": "tool", "name": self.tool, "content": ctx["last_result"]})


class ReplyStep(Step):
    """直接给用户答复的步骤。"""

    def prepare(self, ctx: dict) -> None:
        pass

    def execute(self, ctx: dict) -> str:
        return ctx["reply_text"]

    def finish(self, ctx: dict) -> None:
        ctx["status"] = AgentStatus.DONE


class Harness:
    """Agent 运行时底座调度器:按计划把步骤接成流水线,并记录生命周期事件。"""

    def __init__(self, plan: list):
        self.plan = plan
        self.events: list[Event] = []
        self.ctx = {
            "actions": [],
            "messages": [],
            "reply_text": "当前为上午时段,系统运行状态正常。",
            "last_result": "",
            "status": AgentStatus.RUNNING,
        }

    def build_step(self, spec: dict) -> Step:
        """按规格构建 Step:tool 规格造 ToolStep,其余造 ReplyStep。"""
        if spec["type"] == "tool":
            return ToolStep(spec["name"], spec["tool"])
        return ReplyStep(spec["name"])

    def _log(self, phase: str, step: str, detail: str = "") -> None:
        self.events.append(Event(phase, step, detail))

    def run(self) -> str:
        """按计划调度:每个步骤都走 prepare → execute → finish。"""
        for spec in self.plan:
            step = self.build_step(spec)
            step.prepare(self.ctx)
            self._log("prepare", step.name)
            result = step.execute(self.ctx)
            self.ctx["last_result"] = result
            self._log("execute", step.name, result[:14])
            step.finish(self.ctx)
            self._log("finish", step.name)
            if self.ctx["status"] != AgentStatus.RUNNING:
                break
        return self.ctx["reply_text"]

    def print_events(self) -> None:
        print("\n== 事件回放 ==")
        for ev in self.events:
            print(f"  [{ev.phase:<8}] {ev.step}  {ev.detail}")


def main() -> None:
    plan = [
        {"type": "tool", "name": "get_time", "tool": "get_time"},
        {"type": "tool", "name": "list_meridians", "tool": "list_meridians"},
        {"type": "reply", "name": "reply"},
    ]
    h = Harness(plan)
    reply = h.run()
    print(f"答复: {reply}")
    h.print_events()
    print(f"状态: {h.ctx['status']} | 历史消息: {len(h.ctx['messages'])} 条")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

为Agent 运行时底座设计一套完整的终止条件。除了 s1 的步数保险丝,还要能识别「正常完成」「计划为空」「动作重复」三种停法。四种原因统一用 `StopReason` 枚举表达,由专职函数 `evaluate_stop` 按固定优先级判定,循环本体只负责转动与收场。

### 原理

Agent 循环的「停止决策」是一等公民:模型每轮都在试探下一步,能叫停循环的却只有这四种情形——任务完成(状态进入 DONE)、步数超限(保险丝)、计划为空(规划器两手一摊,无事可做)、动作重复(连续三轮做同一件事,疑似陷入死循环)。把它们统一收进 `evaluate_stop`,循环本体就只剩「决策 → 执行」两件事,停止逻辑可以单独测试、单独演进。判定必须讲究优先级:完成永远优先于超时——哪怕已经踩到步数上限,只要上一轮答完了,就该记 DONE 而不是熔断。REPEAT 检测用「最近 N 个动作完全相同」实现:`set` 去重后只剩一个元素,说明循环在原地打转,立即叫停。终止原因落进 `stop_reason` 字段,配合 `REASON_TEXT` 翻译成人话,报告才有可读性。

### 操作

1. 补全 `evaluate_stop`:依次检查 DONE、MAX_STEPS、EMPTY_PLAN、REPEAT,全部未触发返回 `StopReason.NONE`;
2. 补全 `run` 里的叫停块:记录 `self.stop_reason`,并按原因打印 `[超步]` / `[无动作]` / `[死循环]` 提示;
3. 补全循环末尾:打印终止原因值与 `REASON_TEXT` 译文,再返回答复。

### 常见坑

- 判定顺序不能乱:DONE 必须第一个检查,否则「答完但步数也超了」会被误判成超限;
- EMPTY_PLAN 看的是**当轮计划**,不是历史动作——规划器返回空列表就该停,别等到动作数为零;
- REPEAT 的窗口是「最近三轮」:`state.actions[-repeat_limit:]` 取切片,长度不足时不触发,别把整段历史拿来做 set。

### 目标

同一段剧本,用两种风格实现一遍:手写循环 `hand_written_loop` 用一个函数揉进全部逻辑;Agent 运行时底座则把状态摊进 `AgentState`,交给 `AgentLoop` 驱动。最后用 `compare` 统计两种写法的差异,亲手感受「框架到底替你做了什么」。

### 原理

手写循环是 Agent 开发者的第一反应:一个 `while`、一堆局部变量,决策、执行、判定全写在一起。它跑得通,但三个致命问题随之而来:状态散落在局部变量里,循环每多一个需求,参数列表就多一截;没有统一的停止判定,每个循环各写各的 break;没有数据袋,退出循环后什么都带不出来。Agent 运行时底座的写法则相反——状态是显式的 `AgentState` 五件套(状态、消息、动作、答复、步数),循环是统一的 `AgentLoop`,停止判定是复用的 `evaluate_stop`。两种写法产出相同的结果,差异藏在结构里:`len(manual)` 只有 3 个字段(手写版返回的字典),`len(loop.state.__dict__)` 却有 5 个字段。字段越多,可观测性越强——调试、测试、扩展都建立在「信息有处安放」之上。这就是框架的意义:不是让你少写代码,而是让信息各归其位。

### 操作

1. 补全 `hand_written_loop`:按剧本顺序执行动作,reply 时收场,返回含 reply / actions / steps 的字典;
2. 补全 `compare` 里Agent 运行时底座分支的打印:动作数取 `len(loop.state.actions)`,字段数取 `len(loop.state.__dict__)`;
3. 运行程序,对比两行输出:动作步数相同,信息字段数不同。

### 常见坑

- 手写循环必须保证能退出:剧本走完或 reply 到达都要 break,漏了任何一个都会死循环;
- 别把手写版的数据塞回 dict 之外——返回字典的字段数就是 compare 对比的「信息字段」;
- Agent 运行时底座的字段数是 `__dict__` 里实际存在的键数,不是类里写了几行声明,数错了就答不对题。

### 目标

让Agent 运行时底座从「单轮循环」升级为「多轮会话」:同一台运行时连续接待多轮用户输入,每轮都完整走一遍循环,但消息历史跨轮保留——这就是 Agent 记忆的最小形态。你要补全会话层 `AgentSession`,把每轮的轮次、状态、动作数记成 `TurnRecord`。

### 原理

真实的 Agent 是陪聊的,不是跑一次就散场的。多轮的关键在于「哪些状态每轮重置,哪些跨轮保留」。每轮开始,动作序列、答复、终止原因、步数都要清零——它们描述的是「这一轮做了什么」;消息历史却必须保留——它描述的是「我们一路聊了什么」,Agent 下一轮要参考它才能接上话头。这正好对应两种数据语义:过程状态(per-round)与记忆(per-session)。`AgentSession` 就是负责管理记忆的那一层:它持有循环与历史,每收一条用户输入就驱动一轮循环,并把结果记成 `TurnRecord`——轮次、结束时状态、本轮动作数,三件套足以回答「聊了几轮、每轮聊成了没有、每轮调了几次工具」。会话结束时,report 汇总这些记录:总轮数、总动作步数、消息历史长度,一眼看清整场对话的规模。

### 操作

1. 补全 `AgentSession.run`:调用 `self.loop.run(user_input, script)`,再构造 `TurnRecord`(轮次递增、状态取 `self.loop.state.status`、动作数取 `len(self.loop.state.actions)`)并追加进 `self.turns`;
2. 运行程序,观察三轮会话的输出与 report 汇总;
3. 数一数消息历史:两轮带工具的会话各 2 条,最后一轮只有用户输入 1 条,合计 5 条。

### 常见坑

- 千万别把消息历史也重置了——`state.messages` 是跨轮记忆,重置它就是失忆;
- 轮次从 1 开始递增:`len(self.turns) + 1`,别用循环内部的状态步数当轮次;
- 「动作数」与「消息数」是两个口径:动作数统计工具调用,消息数统计历史条目,report 里不要混用。

steps.solutionCode:
"""Agent 运行时底座 · s5:多轮会话——让运行时常住下来

s4 的循环跑完一轮就散场。真实 Agent 要陪用户聊很多轮,
本步给Agent 运行时底座加上会话层:每轮输入都完整走一遍循环,
但消息历史跨轮保留——Agent 记得上一轮说过什么。
"""
import time
from dataclasses import dataclass, field


class AgentStatus:
    IDLE = "idle"; RUNNING = "running"; DONE = "done"; ERROR = "error"


class StopReason:
    NONE = "none"; DONE = "done"; MAX_STEPS = "max_steps"
    EMPTY_PLAN = "empty_plan"; REPEAT = "repeat"


REASON_TEXT = {
    StopReason.DONE: "任务完成",
    StopReason.MAX_STEPS: "步数超限",
    StopReason.EMPTY_PLAN: "计划为空",
    StopReason.REPEAT: "动作重复",
}


@dataclass
class AgentState:
    """运行数据袋:消息历史跨轮累积,其余字段每轮重置。"""

    status: str = AgentStatus.IDLE
    messages: list = field(default_factory=list)
    actions: list = field(default_factory=list)
    reply: str = ""
    steps: int = 0


def get_time() -> str:
    hour = time.localtime().tm_hour
    labels = ["深夜", "凌晨", "凌晨", "清晨", "早晨", "上午", "中午", "下午", "下午", "傍晚", "夜间", "深夜"]
    return f"当前时间段:{labels[hour % 12]}"


def list_meridians() -> str:
    return "工作流阶段:接收请求、选择工具、执行工具、汇总答复"


TOOLS = {"get_time": get_time, "list_meridians": list_meridians}


def run_tool(name: str) -> str:
    if name not in TOOLS:
        return f"[未知工具] {name}"
    return TOOLS[name]()


def evaluate_stop(state: AgentState, max_steps: int = 10) -> str:
    if state.status == AgentStatus.DONE:
        return StopReason.DONE
    if state.steps >= max_steps:
        return StopReason.MAX_STEPS
    last_three = state.actions[-3:]
    if len(last_three) == 3 and len(set(last_three)) == 1:
        return StopReason.REPEAT
    return StopReason.NONE


class AgentLoop:
    """单轮循环:run 开头重置本轮数据,消息历史跨轮保留。"""

    def __init__(self, max_steps: int = 10):
        self.state = AgentState()
        self.max_steps = max_steps
        self.stop_reason = StopReason.NONE

    def run(self, user_input: str, script: list) -> str:
        state = self.state
        state.status = AgentStatus.RUNNING
        state.steps = 0
        state.actions = []
        state.reply = ""
        self.stop_reason = StopReason.NONE
        state.messages.append({"role": "user", "content": user_input})
        while True:
            reason = evaluate_stop(state, self.max_steps)
            if reason != StopReason.NONE:
                self.stop_reason = reason
                break
            decision = script[state.steps] if state.steps < len(script) else "get_time"
            state.steps += 1
            if decision == "reply":
                state.reply = f"收到:{user_input}——已记下。"
                state.status = AgentStatus.DONE
            else:
                result = run_tool(decision)
                state.actions.append(decision)
                state.messages.append({"role": "tool", "name": decision, "content": result})
        return state.reply


@dataclass
class TurnRecord:
    """一轮对话的记录:轮次、结束时状态、本轮动作数。"""

    turn: int
    status: str
    actions: int


class AgentSession:
    """会话层:带着消息历史连续跑多轮。"""

    def __init__(self, loop: AgentLoop):
        self.loop = loop
        self.turns: list[TurnRecord] = []

    def run(self, user_input: str, script: list) -> str:
        self.loop.run(user_input, script)
        record = TurnRecord(len(self.turns) + 1, self.loop.state.status, len(self.loop.state.actions))
        self.turns.append(record)
        return self.loop.state.reply

    def report(self) -> None:
        for rec in self.turns:
            print(f"第{rec.turn}轮 [{rec.status}] 动作 {rec.actions} 步")
        total_actions = sum(rec.actions for rec in self.turns)
        print(f"共 {len(self.turns)} 轮,动作 {total_actions} 步,消息历史 {len(self.loop.state.messages)} 条")


def main() -> None:
    loop = AgentLoop(max_steps=10)
    session = AgentSession(loop)
    session.run("当前是什么时间段?", ["get_time", "reply"])
    session.run("工作流有哪些主要阶段?", ["get_time", "reply"])
    session.run("我们改天再聊", ["reply"])
    session.report()


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

收官实战:给Agent 运行时底座装上运行轨迹 `trail`。每执行一步,就在轨迹上留下一张快照;跑完整个剧本后,输出三段式运行报告——运行轨迹、统计、终止原因。至此,状态机、生命周期、终止条件、观测能力四件套齐活,一个最小可用的 Agent 运行时完整成形。

### 原理

循环跑得再顺,看不见中间过程就无从调试。轨迹(trail)就是给 Agent 装的「行车记录仪」:每步执行后,把计划动作、执行结果、当时的状态与终止原因打包成一条记录追加进轨迹。记录必须发生在**执行后**——此刻状态已经变化,reason 取的是真实的 `stop_reason`,而不是硬编码的 NONE,否则轨迹永远显示「进行中」,失去诊断价值。比如最后一步 reply:执行后状态是 DONE,终止原因已更新为 done,轨迹里才会出现 `[done/done]`,一眼看出「这一步把任务收尾了」。报告把轨迹、统计、原因三段分开呈现:轨迹回答「怎么走的」,统计回答「走了多少」(计划步数 vs 实际动作——计划允许 3 步,实际只调用了 2 次工具,说明答复不占动作数),终止原因回答「为什么停」。三问齐备,一次运行便完全可审计。

### 操作

1. 补全 `_record`:返回含 plan / result / status / reason 四个字段的字典,status 与 reason 取当前的真实状态值;
2. 在 `run` 的两处补上 `self.trail.append(self._record(...))`:工具步记录工具结果,reply 步记录答复结果;
3. 补全 `print_report`:依次打印运行轨迹(第N步 [status/reason] 计划: plan -> 结果前 12 字)、统计(计划步数 / 实际动作 / 历史消息)、终止原因(值 + REASON_TEXT 译文)。

### 常见坑

- 轨迹的 status / reason 必须读真实状态,别在图省事时硬编码 NONE——快照记录的是执行后的状态,不是执行前的;
- 计划步数取 `len(loop.trail)`,实际动作取 `len(loop.state.actions)`:reply 不调用工具,所以计划 3 步、动作只有 2 步,这是报告的题眼;
- 轨迹 append 之后不要再改 `state.reply` 等字段,否则快照与事实对不上,报告就会撒谎。

### 目标

为章项目「Agent 运行时底座」打好上下文管理的第一块地基:学会给每条消息「称重」。你要实现启发式的 token 估算函数 heuristic_tokens、创建时自动称重的消息类 Message,以及预算账本 TokenBudget(总量、输出预留、可用窗口、剩余空间),最后打印一张完整的上下文账目,确认当前消息放得下。

### 原理

大模型的上下文窗口是硬上限:一次请求里 prompt 装得下多少 token,决定了 Agent 能「记得」多少历史。各家模型的 tokenizer 分词规则各不相同,但绝大多数 token 都来自中文与英文文本——一个足够好的启发式是:CJK 字符每个约 1 token,ASCII 每 4 个字符约 1 token。它不必精确到个位,只要量级正确,就能在真正溢出之前发出预警。预算账本遵循一个朴素的会计原则:总预算(total)等于输出预留(reserve_output)加上下文窗口(max_context)。输出预留是留给模型写回答的「活钱」,绝不能全押在历史里;只有窗口装得下,才谈得上把历史发给模型。

### 操作

1. 实现 Message.__post_init__:消息创建时用 heuristic_tokens 估算内容 token 数,存入 self.tokens;
2. 实现 TokenBudget.remaining:返回窗口剩余空间,即 max_context 减去当前消息总占用;
3. 运行 main,核对打印的账目,确认「预算是否放得下当前消息: True」。

### 常见坑

- token 估算不能返回 0——空字符串至少算 1 个 token,否则剩余空间可能变负,下游逻辑失真;
- 输出预留不是摆设:窗口塞到 100% 是事故前兆,永远给模型留出回复的空间;
- Message 是 dataclass,字段顺序即构造参数顺序,tokens 放在最后用 field(init=False) 自动填充,调用方无需传参。

steps.solutionCode:
"""Agent 运行时底座 · s1:预算先行——给每条消息称重

Agent 的上下文窗口不是无限的,消息装多了就会溢出、截断甚至报错。
本步为「Agent 运行时底座」打地基:用启发式算法估算每条消息的 token 占用,
再把预算、输出预留与可用窗口之间的账目算清楚。"""
import math
import re
from dataclasses import dataclass, field


CJK_RE = re.compile(r"[\u4e00-\u9fff]")


def heuristic_tokens(text: str) -> int:
    """启发式估算 token 数:CJK 每字 1 token,ASCII 每 4 字符 1 token。"""
    cjk = len(CJK_RE.findall(text))
    rest = re.sub(r"\s", "", CJK_RE.sub("", text))
    return max(cjk + math.ceil(len(rest) / 4), 1)


@dataclass
class Message:
    """一条对话消息,创建时自动完成 token 称重。"""

    role: str
    content: str
    tokens: int = field(init=False, default=0)

    def __post_init__(self):
        self.tokens = heuristic_tokens(self.content)


class TokenBudget:
    """上下文预算:总预算、输出预留与可用上下文窗口。"""

    def __init__(self, total: int, reserve_output: int):
        self.total = total
        self.reserve_output = reserve_output
        self.max_context = total - reserve_output

    def used(self, messages) -> int:
        return sum(m.tokens for m in messages)

    def remaining(self, messages) -> int:
        return self.max_context - self.used(messages)

    def fits(self, messages) -> bool:
        return self.used(messages) <= self.max_context


def print_ledger(budget: TokenBudget, messages) -> None:
    """打印上下文账目:总预算、窗口、逐条占用与剩余空间。"""
    print(f"总预算 {budget.total} token,输出预留 {budget.reserve_output}")
    print(f"上下文窗口 {budget.max_context} token")
    for m in messages:
        print(f"  [{m.role}] {m.tokens:>4} token: {m.content[:18]}")
    used = budget.used(messages)
    print(f"已占用 {used} / {budget.max_context} token,剩余 {budget.remaining(messages)}")
    print(f"预算是否放得下当前消息: {budget.fits(messages)}")


def main() -> None:
    budget = TokenBudget(total=8000, reserve_output=2000)
    history = [
        Message("system", "你是Agent 运行时底座的守门人,负责守护一座校园项目的运转。"),
        Message("user", "请汇报校园项目今日的运行资源收支情况,并给出三条建议。"),
        Message("assistant", "遵命。今日运行资源收入 5200,支出 3100,结余 2100。"),
        Message("user", "结余部分建议怎么处理?请说得详细一些。"),
        Message("assistant", "建议:一扩充内容制作环境,二修缮监控系统,三储备过冬预算点。"),
    ]
    print_ledger(budget, history)


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

给「Agent 运行时底座」装上第一个真正落地的清理策略——滑动窗口。当历史消息装不进预算时,用 trim_window 从最新往最旧保留消息,system 指令永远不动,塞不下的旧消息整段丢弃,并返回丢弃数量与保留列表。

### 原理

对话有个朴素规律:「最近的最相关」。用户当前的问题依赖最近几轮上下文,而十轮前的寒暄价值趋近于零。滑动窗口正是这一观察的直白实现——像一块贴着最新消息滑动的挡板,窗口里永远是最新的一段。与逐条随机删除不同,滑动窗口保持对话的连续性:模型看到的始终是一段完整、连贯、以最新消息结尾的对话,而不是千疮百孔的历史。system 指令是例外中的例外:它定义 Agent 的角色与行为规则,优先级最高,无论窗口多窄都必须保留——所以窗口算法要把 system 单独拎出来,先从它起步。

### 操作

1. 在 trim_window 里先把 system 消息放入 kept;
2. 从最新往最旧逐条尝试:把当前消息临时插到 kept 最前,若 budget.fits 则保留,否则 break;
3. 运行 main,核对截断后的保留数与丢弃数,并确认最终用量落在窗口内。

### 常见坑

- 遍历方向别搞反:必须从最新开始倒着扫,否则最先丢掉的是最新消息;
- system 判断用 role == "system",不要用索引硬编码——消息列表结构可能变化;
- trim 返回 (kept, dropped) 二元组,调用方两者都要用,别只 return kept。

steps.solutionCode:
"""Agent 运行时底座 · s2:滑动窗口——塞不下的历史整体裁剪

预算定好了,可对话一长,窗口照样会撑爆。本步实现「滑动窗口」:
从最新往回保留消息,system 指令永远在,塞不下的旧消息整批丢弃,
保证每次请求都装得进预算。"""
import math
import re
from dataclasses import dataclass, field


CJK_RE = re.compile(r"[\u4e00-\u9fff]")


def heuristic_tokens(text: str) -> int:
    """启发式估算 token 数:CJK 每字 1 token,ASCII 每 4 字符 1 token。"""
    cjk = len(CJK_RE.findall(text))
    rest = re.sub(r"\s", "", CJK_RE.sub("", text))
    return max(cjk + math.ceil(len(rest) / 4), 1)


@dataclass
class Message:
    """一条对话消息,创建时自动完成 token 称重。"""

    role: str
    content: str
    tokens: int = field(init=False, default=0)

    def __post_init__(self):
        self.tokens = heuristic_tokens(self.content)


class TokenBudget:
    """上下文预算:总预算、输出预留与可用上下文窗口。"""

    def __init__(self, total: int, reserve_output: int):
        self.total = total
        self.reserve_output = reserve_output
        self.max_context = total - reserve_output

    def used(self, messages) -> int:
        return sum(m.tokens for m in messages)

    def fits(self, messages) -> bool:
        return self.used(messages) <= self.max_context


def trim_window(messages, budget):
    """滑动窗口裁剪:system 必留,从最新往最旧收,塞不下就停。"""
    kept = []
    if messages and messages[0].role == "system":
        kept.append(messages[0])
    for m in reversed(messages[len(kept):]):
        if budget.fits([m] + kept):
            kept.insert(0, m)
        else:
            break
    return kept, len(messages) - len(kept)


def main() -> None:
    budget = TokenBudget(total=900, reserve_output=750)
    history = [
        Message("system", "你是Agent 运行时底座,负责在有限窗口里保住关键对话。"),
        Message("user", "第1轮:请评估校园项目运行资源枯竭的风险等级。"),
        Message("assistant", "风险等级为高:网络受损三成,且恢复速度远低于消耗。"),
        Message("user", "第2轮:高风险的依据是什么?把数据列出来。"),
        Message("assistant", "依据:运行资源入不敷出已连续九个月,库存仅剩两成。"),
        Message("user", "第3轮:库存两成还能支撑多久?给出估算。"),
        Message("assistant", "按当前消耗速度,预计还能支撑约四个月,须尽快行动。"),
        Message("user", "第4轮:请把治理方案按紧急程度排序。"),
        Message("assistant", "排序:一修网络,二暂停非必要任务,三引援,四扩充工作流。"),
    ]
    kept, dropped = trim_window(history, budget)
    print(f"截断后 {len(kept)} 条,丢弃 {dropped} 条,用量 {budget.used(kept)} / {budget.max_context} token")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

实现把「旧对话压成一行浓缩信息」的滚动摘要能力:先写 make_summary,把一批旧消息逐条取首句、拼成一行摘要并截断到上限;再用 SummaryBuffer 封装摘要缓冲,攒够旧消息就折叠出新的摘要消息。最后运行 main,验证压缩后的消息条数与窗口用量。

### 原理

上下文管理里有一类专门对付「旧但还有用」消息的招数:滚动摘要。它不把旧消息原样删掉,而是把最旧的一批压缩成一句话——保留「谁说了什么」的骨架,丢掉细节。token 账上是巨亏转盈:一条几十 token 的消息,压成摘要后只占几个 token 的份额。摘要的通用形态是「角色:首句」:user:问题,assistant:回答,再用分号串成一行。这个形态对模型友好——它看起来仍然像一段对话,只是更短。折叠出来的摘要消息本身也是消息,可以继续参与下一轮折叠:摘要套摘要,这正是「滚动」二字的意思。

### 操作

1. 实现 make_summary:遍历消息,取每条内容按「。」切出的首句,拼成「角色:首句」追加进 parts;
2. 用「;」连接 parts,截断到 max_chars 上限后返回;
3. 实现 SummaryBuffer.fold:已有旧摘要时把它作为 system 消息接到最前面,再生成新摘要,返回参与折叠的消息数;
4. 运行 main,核对打印的折叠条数与压缩后的窗口用量。

### 常见坑

- 摘要必须截断:不截断的话,折叠几轮之后摘要比原对话还长,滚动摘要就失去了意义;
- 旧摘要不能丢:fold 时若 self.text 非空,必须把旧摘要作为 system 消息一起压缩,否则信息层层丢失;
- 摘要消息要带「过往摘要」前缀,一眼认出它是浓缩产物,也方便上层日志排查。

steps.solutionCode:
"""Agent 运行时底座 · s3:滚动摘要——旧对话压成一行浓缩信息

对话越长,历史越重,窗口迟早被撑爆。与其把旧消息原样搬进窗口,
不如把最旧的一批先压成一句话摘要,再用这条摘要代表它们。
本步实现 make_summary:把多条旧消息浓缩成一行中文摘要。"""
import math
import re
from dataclasses import dataclass


CJK_RE = re.compile(r"[\u4e00-\u9fff]")


def heuristic_tokens(text: str) -> int:
    """启发式估算 token 数:CJK 每字 1 token,ASCII 每 4 字符 1 token。"""
    cjk = len(CJK_RE.findall(text))
    rest = re.sub(r"\s", "", CJK_RE.sub("", text))
    return max(cjk + math.ceil(len(rest) / 4), 1)


@dataclass
class Message:
    """一条对话消息:角色 + 内容,token 数惰性估算。"""
    role: str
    content: str

    @property
    def tokens(self) -> int:
        return heuristic_tokens(self.content)


@dataclass
class TokenBudget:
    """窗口预算:总量 - 输出预留 = 可用上下文。"""
    total: int = 900
    reserve_output: int = 700

    @property
    def max_context(self) -> int:
        return self.total - self.reserve_output

    def fits(self, messages) -> bool:
        return self.used(messages) <= self.max_context

    def used(self, messages) -> int:
        return sum(m.tokens for m in messages)


def make_summary(messages, max_chars: int = 100) -> str:
    """把多条旧消息压成一行摘要:取每条的首句拼接。"""
    parts = []
    for m in messages:
        first = m.content.split("。")[0]
        parts.append(f"{m.role}:{first}")
    text = ";".join(parts)
    return text[:max_chars]


class SummaryBuffer:
    """摘要缓冲:攒够一批旧消息就压成一条摘要消息。"""
    def __init__(self, max_chars: int = 100):
        self.max_chars = max_chars
        self.text = ""

    def fold(self, messages) -> int:
        if self.text:
            messages = messages + [Message("system", self.text)]
        self.text = make_summary(messages, self.max_chars)
        return len(messages)

    def as_message(self) -> Message:
        return Message("system", "【过往摘要】" + self.text)


def main() -> None:
    budget = TokenBudget(total=900, reserve_output=700)
    history = [
        Message("system", "你是Agent 运行时底座,负责把旧对话压缩成摘要。"),
        Message("user", "第1轮:网络吞吐几何?"),
        Message("assistant", "网络每日吞吐三千预算点。"),
        Message("user", "第2轮:模型服务状态如何?"),
        Message("assistant", "丹模型服务候稳定,可炼上品丹。"),
        Message("user", "第3轮:监控系统运转正常吗?"),
        Message("assistant", "监控系统一切正常,无破损。"),
    ]
    summary = SummaryBuffer(max_chars=100)
    folded = summary.fold(history[1:4])
    print(f"折叠 {folded} 条,摘要: {summary.text}")
    current = history[:1] + history[4:] + [summary.as_message()]
    print(f"压缩后 {len(current)} 条 + 1 条摘要,用量 {budget.used(current)} / {budget.max_context} token")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

实现「低价值消息逐个让位」的重要性淘汰:先写 importance_score,给每条消息按角色、时新度、内容量打一个综合分;再写 evict_low_importance,在窗口放不下时反复弹出得分最低且非 system 的消息,直到装得下。运行 main,验证淘汰条数与留存后的窗口用量。

### 原理

摘要擅长压缩「旧对话」,但它并不适合所有消息:有些消息(工具返回、最新指令)不该被压成一行,它们的信息密度太高。于是换第二种处置:重要性淘汰。给每条消息打一个分,分数由三块组成——角色基础分(tool 最高、user 次之、assistant 再次,未知角色保底)、时新度加分(越新的消息分越高,与位置成正比)、内容量加分(信息越多越值得留,但封顶)。system 消息直接给满分 1000,任何淘汰都不许碰它。淘汰的过程不是一次算完再批量删,而是「while 装不下就弹一条最低分」的循环:每次重新打分,因为消息的位置变了,时新度也跟着变。

### 操作

1. 实现 importance_score:system 返回 1000.0;其余按角色取基础分,加上时新度与内容量加分后返回;
2. 实现 evict_low_importance:复制消息列表,装不下时枚举所有非 system 消息,弹出得分最低的一条,把内容前 16 字记入 victims;
3. 运行 main,核对「被淘汰」列表与留存后的窗口用量。

### 常见坑

- system 必须双保险豁免:评分给 1000 分,淘汰循环里还要显式排除 role == "system",缺一不可;
- 得分相同要有个稳定的决出办法:min 时把内容本身作为第二关键字,结果才可复现;
- 淘汰是逐条的:别试图一次删多条——位置变了分数就变了,逐条弹才能弹得准。

steps.solutionCode:
"""Agent 运行时底座 · s4:重要性淘汰——低价值消息逐个让位

摘要擅长压缩旧对话,但有些消息不该被压扁:工具返回、最新指令信息密度太高。
本步换一条思路:给每条消息打重要性分,窗口放不下时就弹出得分最低的,
直到装下为止——低价值消息逐个让位。"""
import math
import re
from dataclasses import dataclass


CJK_RE = re.compile(r"[\u4e00-\u9fff]")


def heuristic_tokens(text: str) -> int:
    """启发式估算 token 数:CJK 每字 1 token,ASCII 每 4 字符 1 token。"""
    cjk = len(CJK_RE.findall(text))
    rest = re.sub(r"\s", "", CJK_RE.sub("", text))
    return max(cjk + math.ceil(len(rest) / 4), 1)


@dataclass
class Message:
    """一条对话消息:角色 + 内容,token 数惰性估算。"""
    role: str
    content: str

    @property
    def tokens(self) -> int:
        return heuristic_tokens(self.content)


@dataclass
class TokenBudget:
    """窗口预算:总量 - 输出预留 = 可用上下文。"""
    total: int = 900
    reserve_output: int = 850

    @property
    def max_context(self) -> int:
        return self.total - self.reserve_output

    def fits(self, messages) -> bool:
        return self.used(messages) <= self.max_context

    def used(self, messages) -> int:
        return sum(m.tokens for m in messages)


def importance_score(m, index: int, total: int) -> float:
    """重要性打分:角色基础分 + 时新度加分 + 内容量加分。"""
    if m.role == "system":
        return 1000.0
    base = {"tool": 80.0, "user": 60.0, "assistant": 40.0}.get(m.role, 30.0)
    recency = 20.0 * index / max(total, 1)
    size = min(m.tokens * 0.5, 30.0)
    return base + recency + size


def evict_low_importance(messages, budget):
    """淘汰低价值消息:反复弹出重要性最低且非 system 的一条。"""
    kept = list(messages)
    victims = []
    while not budget.fits(kept):
        candidates = [i for i, m in enumerate(kept) if m.role != "system"]
        idx = min(candidates, key=lambda i: (importance_score(kept[i], i, len(kept)), kept[i].content))
        victims.append(kept.pop(idx).content[:16])
    return kept, victims


def main() -> None:
    budget = TokenBudget(total=900, reserve_output=850)
    history = [
        Message("system", "你是Agent 运行时底座,负责在窗口紧张时淘汰低价值消息。"),
        Message("user", "第1轮:参考资料库存几何?"),
        Message("assistant", "参考资料库存三千二百株。"),
