# === 学习契约结束 ===
from abc import ABC, abstractmethod


class Plugin(ABC):
    def __init__(self, name, version, description):
        self.name = name
        self.version = version
        self.description = description

    @abstractmethod
    def run(self, text):
        """处理一条输入,返回结果字符串。"""

    def on_install(self):
        """安装回调:给插件一个自我介绍的舞台。"""


