    rt = HookRuntime(plugins)
    counts = rt.bus.counts()
    print(f"订阅情况: request_in={counts.get('request_in', 0)} request_out={counts.get('request_out', 0)}")
    print("--- 正常请求 ---")
    rt.handle("你好,Agent 运行时底座")
    print("--- 违规请求 ---")
    rt.handle("这个请求禁止执行")


