import time
from dataclasses import dataclass, field

_ID_GEN = itertools.count(1)


def _next_id() -> int:
    return next(_ID_GEN)


def _now() -> str:
    return time.strftime("%Y-%m-%d %H:%M:%S")


@dataclass
class Message:
    """一条 Agent 消息:谁发的、发给谁、什么主题、什么内容。"""

    sender: str
    topic: str
    payload: dict
    receiver: str = "*"
    msg_id: int = field(default_factory=_next_id)
    ts: str = field(default_factory=_now)

    def to_dict(self) -> dict:
        """把消息转成普通字典,方便落库、审计与序列化。"""
        return {
            "msg_id": self.msg_id,
            "ts": self.ts,
            "sender": self.sender,
            "receiver": self.receiver,
            "topic": self.topic,
            "payload": self.payload,
        }

    def __str__(self) -> str:
        """人类可读的消息摘要,日志与调试都靠它。"""
        return f"[{self.ts}] {self.sender} -> {self.receiver} <{self.topic}> {self.payload}"


def make_messages() -> list[Message]:
    """模拟校园 AI 社一天里的三条消息:任务分派、进度汇报、系统告警。"""
    return [
        Message(sender="product_manager", topic="task.assign",
                payload={"task": "实现登录页", "assignee": "dev_1"}),
        Message(sender="dev_1", topic="report.progress",
                payload={"task": "实现登录页", "percent": 60}),
        Message(sender="ops_1", topic="alarm.critical",
                payload={"service": "gateway", "latency": 3200}),
    ]


def main() -> None:
    for msg in make_messages():
        print(msg)
    print("== 序列化为字典 ==")
    for msg in make_messages():
        for key, value in msg.to_dict().items():
            print(f"  {key}: {value}")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

让消息不再「点对点直连」,而是投进一条共享的发布订阅总线。你将在 s1 的消息协议之上实现 `MessageBus`:订阅方按主题登记回调,发布方把消息交给总线,总线按主题把消息派发给所有订阅者,并保留一份完整审计记录。

### 原理

发布订阅(pub/sub)把「消息生产」与「消息消费」彻底解耦:发布方不需要知道谁在听,订阅方不需要知道谁在发,双方只认「主题」这个契约。总线的核心是一张订阅表——`topic → [handler1, handler2, ...]`;`publish` 时先写入审计列表 `published`,再遍历订阅表,把消息逐个派发给主题匹配的处理器。每个订阅者的异常用 `try/except` 单独隔离:一个订阅者挂了,不影响其他人收消息。用 `defaultdict(list)` 建订阅表,`subscribe` 时不用先判断主题是否存在,`self._subs[topic].append(handler)` 一行搞定。

### 操作

1. 实现 `MessageBus.subscribe(topic, handler)`,把回调注册到 `self._subs[topic]`;
2. 实现 `MessageBus.publish(msg)`:先记入 `self.published` 审计,再按 `topic == msg.topic` 精确匹配派发,单个订阅者异常要隔离;
3. 运行脚本,验证三条消息中前两条被 `[日志]` 打印,第三条 `alarm.critical` 无人订阅而静默,审计区显示 3 条,最后列出注册主题。

### 常见坑

- 派发循环里遍历的是 `list(self._subs.items())` 的拷贝——回调内部若修改订阅表,不会破坏正在进行的派发;
- `topics()` 要返回 `sorted(self._subs)` 排好序的列表,而不是字典本身,否则输出顺序不稳定;
- 订阅者的异常要在 `publish` 里拦截,不要在订阅回调里 try——回调是别人的代码,你管不到它内部怎么处理。

