"""校园 AI 社 · s2:发布订阅总线 —— 消息不再直达,交给总线分发。"""
import itertools
import time
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Callable

_ID_GEN = itertools.count(1)


def _next_id() -> int:
    return next(_ID_GEN)


def _now() -> str:
    return time.strftime("%Y-%m-%d %H:%M:%S")


@dataclass
class Message:
    """与 s1 相同:一条 Agent 消息。"""

    sender: str
    topic: str
    payload: dict
    receiver: str = "*"
    msg_id: int = field(default_factory=_next_id)
    ts: str = field(default_factory=_now)

    def to_dict(self) -> dict:
        return {
            "msg_id": self.msg_id,
            "ts": self.ts,
            "sender": self.sender,
            "receiver": self.receiver,
            "topic": self.topic,
            "payload": self.payload,
        }

    def __str__(self) -> str:
        return f"[{self.ts}] {self.sender} -> {self.receiver} <{self.topic}> {self.payload}"


class MessageBus:
    """按主题分发消息的发布订阅总线。"""

    def __init__(self) -> None:
        self._subs: dict[str, list[Callable]] = defaultdict(list)
        self.published: list[Message] = []

    def subscribe(self, topic: str, handler: Callable) -> None:
        self._subs[topic].append(handler)

    def publish(self, msg: Message) -> None:
        self.published.append(msg)
        for topic, handlers in list(self._subs.items()):
            if topic != msg.topic:
                continue
            for handler in handlers:
                try:
                    handler(msg)
                except Exception as exc:
                    print(f"[总线] 订阅者异常: {exc}")

    def topics(self) -> list[str]:
        return sorted(self._subs)


def log_handler(msg: Message) -> None:
    """通用日志订阅者:收到任何消息都打印一行。"""
    print(f"[日志] {msg}")


def main() -> None:
    bus = MessageBus()
    bus.subscribe("task.assign", log_handler)
    bus.subscribe("report.progress", log_handler)
    bus.publish(Message(sender="product_manager", topic="task.assign",
                        payload={"task": "实现登录页", "assignee": "dev_1"}))
    bus.publish(Message(sender="dev_1", topic="report.progress",
                        payload={"task": "实现登录页", "percent": 60}))
    bus.publish(Message(sender="ops_1", topic="alarm.critical",
                        payload={"service": "gateway", "latency": 3200}))
    print("== 总线审计:共发布 3 条消息 ==")
    for m in bus.published:
        print(f"#{m.msg_id} {m.topic} from {m.sender}")
    print(f"注册主题: {bus.topics()}")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

把 s2 的「精确主题匹配」升级为「通配符订阅」:订阅 `task.*` 一次收下 `task.assign`、`task.done` 等所有二级主题;订阅 `alarm.#` 收下任意层级的告警。你要实现 `topic_match(pattern, topic)` 匹配函数,并把订阅表改造成「模式 + 回调」的列表。

### 原理

精确订阅下,订阅方要为每个主题重复登记,消息一多就烦。借鉴 MQTT 的主题层级思想:`*` 匹配恰好一层,`#` 匹配剩余任意层(可以为空)。例如 `task.*` 能匹配 `task.assign` 但匹配不了 `task.assign.rev`;`task.#` 既能匹配 `task.assign` 也能匹配 `task.assign.rev`。匹配算法把主题按 `.` 切成段,逐段比较:遇到 `#` 直接命中;遇到 `*` 跳过本层;普通段必须相等;最后还要比较段数——这就是「`*` 只吃一层、`#` 吃无限层」的实现关键。订阅表从「主题 → 回调列表」的字典变成「(模式, 回调)」的列表,`publish` 时逐个用 `topic_match` 试配。

### 操作

1. 实现 `topic_match(pattern, topic)`,按上述规则返回布尔值;
2. 改造 `MessageBus.subscribe`:把 `(pattern, handler)` 二元组追加进 `self._subs`;
3. 改写 `publish`:遍历订阅表,用 `topic_match(pattern, msg.topic)` 判断是否派发;
4. 实现 `counts()` 按主题统计消息条数;运行脚本,验证 `[看板]` 收到三条 task 消息、`[告警]` 收到一条 alarm 消息。

### 常见坑

- `#` 要在逐段比较的**开头就 return True**,而不是把它当成普通段比完再放行——它吞掉剩余所有层,直接返回即可;
- 段数比较放在最后:只有整个模式段都匹配、且双方段数一致才返回 True,漏掉它 `task.*` 会错误匹配三层主题;
- `publish` 遍历时要拷贝订阅表快照,防止回调里新增订阅影响本轮派发。

