"""校园 AI 社 · s6:迷你校园 AI 社实战 —— 四路消息汇成一张作战黑板。"""
import itertools
import time
from collections import Counter
from dataclasses import dataclass, field
from typing import Any, Callable

_ID_GEN = itertools.count(1)


def _next_id() -> int:
    return next(_ID_GEN)


def _now() -> str:
    return time.strftime("%Y-%m-%d %H:%M:%S")


@dataclass
class Message:
    """一条 Agent 消息:谁发的、发给谁、什么主题、什么内容。"""

    sender: str
    topic: str
    payload: dict
    receiver: str = "*"
    msg_id: int = field(default_factory=_next_id)
    ts: str = field(default_factory=_now)


def topic_match(pattern: str, topic: str) -> bool:
    """通配符匹配:* 恰好一层,# 匹配任意剩余层(可为空)。"""
    p_parts = pattern.split(".")
    t_parts = topic.split(".")
    for i, p in enumerate(p_parts):
        if p == "#":
            return True
        if i >= len(t_parts):
            return False
        if p != "*" and p != t_parts[i]:
            return False
    return len(p_parts) == len(t_parts)


class MessageBus:
    """支持通配符订阅的发布订阅总线。"""

    def __init__(self) -> None:
        self._subs: list[tuple[str, Callable]] = []
        self.published: list[Message] = []

    def subscribe(self, pattern: str, handler: Callable) -> None:
        self._subs.append((pattern, handler))

    def publish(self, msg: Message) -> None:
        self.published.append(msg)
        for pattern, handler in list(self._subs):
            if not topic_match(pattern, msg.topic):
                continue
            try:
                handler(msg)
            except Exception as exc:
                print(f"[总线] 订阅者异常: {exc}")


class Blackboard:
    """精简版共享黑板:数据 + 写入历史,配合总线使用。"""

    def __init__(self) -> None:
        self._data: dict[str, Any] = {}
        self.history: list[dict] = []

    def write(self, key: str, value: Any, author: str = "unknown") -> None:
        version = sum(1 for h in self.history if h["key"] == key) + 1
        self._data[key] = value
        self.history.append({"author": author, "key": key, "value": value, "version": version})

    def read(self, key: str) -> Any:
        return self._data.get(key)

    def keys(self) -> list[str]:
        return sorted(self._data)


def blackboard_bridge(bus: MessageBus, board: Blackboard) -> None:
    """把 task.# 系列消息统统沉淀到黑板:键是 task.{任务}.{事件},值是整条 payload。"""
    def handler(msg: Message) -> None:
        task = msg.payload.get("task")
        event = msg.topic.split(".")[-1]
        board.write(f"task.{task}.{event}", msg.payload, msg.sender)
    bus.subscribe("task.#", handler)


def qa_gate(bus: MessageBus, board: Blackboard) -> None:
    """质检官:进度 100% 且带 commit 的任务才放行,结果广播到总线。"""
    def handler(msg: Message) -> None:
        task = msg.payload.get("task")
        passed = msg.payload.get("percent") == 100 and bool(msg.payload.get("commit"))
        board.write(f"task.{task}.qa", "通过" if passed else "打回", "qa_1")
        bus.publish(Message(sender="qa_1", topic="task.accepted" if passed else "task.rejected",
                            payload={"task": task, "qa": "通过" if passed else "打回"}))
    bus.subscribe("task.done", handler)


def daily_report(bus: MessageBus, board: Blackboard) -> None:
    """收工日报:消息流水 + 主题统计 + 黑板快照。"""
    print("===== 校园 AI 社日报 =====")
    for m in bus.published:
        print(f"  #{m.msg_id} [{m.ts}] {m.sender} -> {m.topic} {m.payload}")
    stat = dict(Counter(m.topic for m in bus.published))
    print(f"主题统计: {stat}")
    print("黑板快照:")
    for k in board.keys():
        print(f"  {k} = {board.read(k)}")
    print("===== 日报结束 =====")


def main() -> None:
    bus = MessageBus()
    board = Blackboard()
    blackboard_bridge(bus, board)
    qa_gate(bus, board)
    bus.publish(Message(sender="product_manager", topic="task.assign", payload={"task": "实现登录页", "assignee": "dev_1"}))
    bus.publish(Message(sender="dev_1", topic="task.accept", payload={"task": "实现登录页"}))
    bus.publish(Message(sender="dev_1", topic="task.progress", payload={"task": "实现登录页", "percent": 50}))
    bus.publish(Message(sender="dev_1", topic="task.done", payload={"task": "实现登录页", "percent": 100, "commit": "abc123"}))
    daily_report(bus, board)


if __name__ == "__main__":
    main()

"""校园 AI 社 · s1:任务契约与分派策略

社长在项目工作台统一协调,把一份需求文档拆成一张张任务单,按社团成员专长分派。
本步定义协作的语言——任务单 AgentTask 与完工汇报 TaskResult,
再用关键词路由表把任务分给前端、后端、测试、文档四位社团成员。
"""
from dataclasses import dataclass


@dataclass
class AgentTask:
    """一张任务单:编号、标题、负责人、载荷。"""
    id: str
    title: str
    assignee: str = ""
    payload: str = ""


@dataclass
class TaskResult:
    """一张完工汇报:谁干的、干成了没、交出了什么。"""
    task_id: str
    assignee: str
    ok: bool
    data: str = ""


# 关键词路由表:按任务标题里的关键词决定派给哪位社团成员
SKILL_ROUTES = [
    (("前端", "页面", "界面"), "前端同学"),
    (("接口", "后端", "服务"), "后端同学"),
    (("测试", "用例"), "测试同学"),
    (("文档", "说明"), "文档同学"),
]


def route_task(task: AgentTask) -> str:
    """按标题关键词匹配路由表;匹配不到落给后端同学。"""
    for keywords, assignee in SKILL_ROUTES:
        if any(k in task.title for k in keywords):
            return assignee
    return "后端同学"


def assign_tasks(requests: list[str]) -> list[AgentTask]:
    """把需求文档拆成任务单并分派,返回带负责人的任务单列表。"""
    tasks = []
    for i, req in enumerate(requests, start=1):
        task = AgentTask(id=f"t{i}", title=req)
        task.assignee = route_task(task)
        tasks.append(task)
    return tasks


def specialist_work(task: AgentTask) -> TaskResult:
    """社团成员开工:按专长产出模拟成果,写成完工汇报。"""
    if task.assignee == "前端同学":
        data = f"已产出页面骨架: {task.title}"
    elif task.assignee == "测试同学":
        data = f"已编写测试用例 {len(task.title)} 条,全部通过"
    elif task.assignee == "文档同学":
        data = f"文档已更新: {task.title}"
    else:
        data = f"后端接口已就绪: {task.title}"
    return TaskResult(task_id=task.id, assignee=task.assignee, ok=True, data=data)


def main() -> None:
    requests = ["前端页面设计", "后端接口联调", "登录模块测试", "接口使用文档"]
    tasks = assign_tasks(requests)
    print("== 校园 AI 社任务分派 ==")
    for t in tasks:
        print(f"  {t.id} {t.title} -> {t.assignee}")
    print("== 社团成员开工 ==")
    for t in tasks:
        r = specialist_work(t)
        print(f"  [{r.assignee}] {r.data}")


if __name__ == "__main__":
    main()

"""校园 AI 社 · s3:分派、执行与返工

把迷你状态图拼成 Supervisor 编排骨架:拆需求 -> 派活 -> 执行 -> 检查,
用 FAIL_ONCE 模拟偶发故障,t2 首跑失败后经返工回路收敛。
"""
from dataclasses import dataclass
from typing import TypedDict

from langgraph.graph import END, START, StateGraph


@dataclass
class AgentTask:
    id: str
    title: str
    assignee: str = ""
    payload: str = ""


@dataclass
class TaskResult:
    task_id: str
    assignee: str
    ok: bool
    data: str = ""
    error: str = ""


# 模拟偶发故障:t2 首跑必败,返工后恢复正常
FAIL_ONCE = {"t2"}


class WorkflowState(TypedDict, total=False):
    request: str
    tasks: list[AgentTask]
    results: list[TaskResult]
    retried: bool


def split_node(state: dict) -> dict:
    tasks = [AgentTask(id=f"t{i}", title=t, assignee="后端同学")
             for i, t in enumerate(state["request"].split("和"), start=1)]
    return {"tasks": tasks}


def execute_node(state: dict) -> dict:
    results = []
    for t in state["tasks"]:
        if t.id in FAIL_ONCE:
            results.append(TaskResult(task_id=t.id, assignee=t.assignee, ok=False,
                                      error="偶发故障:服务超时"))
        else:
            results.append(TaskResult(task_id=t.id, assignee=t.assignee, ok=True,
                                      data=f"后端接口已就绪: {t.title}"))
    return {"results": results}


def router_after_execute(state: dict) -> str:
    return "retry" if any(not r.ok for r in state["results"]) else "END"


def retry_node(state: dict) -> dict:
    FAIL_ONCE.clear()  # 故障已排除,下一轮执行恢复正常
    return {"retried": True}


def main() -> None:
    builder = StateGraph(WorkflowState)
    builder.add_node("split", split_node)
    builder.add_node("execute", execute_node)
    builder.add_node("retry", retry_node)
    builder.add_edge(START, "split")
    builder.add_edge("split", "execute")
    builder.add_conditional_edges("execute", router_after_execute, {"retry": "retry", "END": END})
    builder.add_edge("retry", "execute")
    graph = builder.compile()
    state = graph.invoke({"request": "前端页面设计和后端接口联调"}, {"recursion_limit": 10})
    print(f"校园 AI 社使用 LangGraph{'(含返工)' if state.get('retried') else ''},共 {len(state['tasks'])} 张任务单:")
    for r in state["results"]:
        print(f"  · {r.assignee}: {r.data}")
    print("全部完工,可交付。")


if __name__ == "__main__":
    main()

