"""校园 AI 社 · s1：用真实 CrewAI Agent 定义团队角色。"""
import os
import sys

from crewai import Agent, LLM


def build_llm() -> LLM:
    api_key = os.environ.get("OPENAI_API_KEY", "").strip()
    if not api_key:
        print("请先在右上角 AI 配置填入 DeepSeek API Key，然后重新运行。")
        sys.exit(2)
    return LLM(model=f"openai/{os.environ.get('MODEL_NAME', 'deepseek-chat')}", api_key=api_key,
               base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"), temperature=0)


def build_heaven(llm: LLM) -> list[Agent]:
    return [
        Agent(role="产品经理", goal="把用户诉求翻译成可验收需求", backstory="最懂用户问题", llm=llm),
        Agent(role="后端工程师", goal="设计可靠 API", backstory="契约优先", llm=llm),
        Agent(role="前端工程师", goal="实现清晰界面", backstory="关注交互细节", llm=llm),
        Agent(role="测试工程师", goal="发现交付风险", backstory="只认可可复现证据", llm=llm),
    ]


def main() -> None:
    for agent in build_heaven(build_llm()):
        print(f"{agent.role}: {agent.goal}")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

为章项目「微型模型实验」搭建微型 GPT 的数据管道,本步是源头——语料清洗与字符统计。你要把三首古诗拼成的原始语料 `CORPUS` 清洗成纯净字符串,统计每个字符的出现次数,并建立「字符 ↔ 序号」的双向映射词表。这份词表是后面 BPE 训练和数据集构建的地基:模型不认识汉字,只认数字。

### 原理

语言模型吃的是 token 序列,而 token 底层是整数 id。把语料变成 id 的第一层转换叫「字符级词表」:`sorted(set(text))` 得到全部去重字符,按字典序从 0 开始编号;`char_to_id` 负责「查字给号」,`id_to_char` 负责「查号给字」,两者互为逆映射。清洗是为了去噪:全角空格 `\u3000`、控制字符等不可打印字符既不是古诗的一部分,也会让词表虚胖、让后面的字对统计失真,所以必须先过滤再建表。`Counter` 则是统计利器,一句 `Counter(text)` 就能得到每个字符的频次,`most_common(5)` 直接取前五。

### 操作

1. 补全 `clean_text`:先把全角空格替换为空串,再用 `str.isprintable()` 过滤不可打印字符,`join` 后返回;
2. 补全 `build_char_vocab`:`chars = sorted(set(text))` 已给出,请建立 `char_to_id` 与 `id_to_char` 两个字典;
3. 运行 `main`,确认输出「语料长度: 72 个字符」「词表大小: 38 个字符」与频次 TOP5。

### 常见坑

- 两个字典必须互为逆映射:`id_to_char[i] == ch` 对每个 `(ch, i) in char_to_id.items()` 都要成立,写反了后面 decode 全是乱码;
- 清洗要在建表之前:先过滤再 `set(text)`,否则全角空格会混进词表凑数;
- 语料里逗号与句号也算字符,统计 TOP5 时「,」「。」会排在最前面,这不是 bug。

steps.solutionCode:
"""t60 · s1:语料清洗与字符统计

模型研究小组的第一步,是为微型 GPT 准备「口粮」:把散落的古诗语料
清洗成规整文本,统计每个字符的出现频率,再建立字符与序号之间的
双向映射——这就是最朴素的词表(char vocab)。
"""
from collections import Counter

# 三首古诗拼成的语料:前两首各重复两遍,保证字对有足够频次
CORPUS = (
    "床前明月光,疑是地上霜。举头望明月,低头思故乡。"
    "床前明月光,疑是地上霜。举头望明月,低头思故乡。"
    "白日依山尽,黄河入海流。欲穷千里目,更上一层楼。"
)


def _is_printable(ch: str) -> bool:
    """单字是否保留:只留可打印字符(汉字、中文标点),滤掉控制符。"""
    return ch.isprintable()


def clean_text(text: str) -> str:
    """清洗语料:剔除全角空格与不可打印字符,返回纯净字符串。"""
    text = text.replace("\u3000", "")
    return "".join(ch for ch in text if _is_printable(ch))


def char_stats(text: str) -> Counter:
    """统计每个字符出现的次数,返回 Counter。"""
    return Counter(text)


def freq_table(text: str, k: int = 5) -> list:
    """按频次从高到低取前 k 个 (字符, 次数) 对。"""
    return char_stats(text).most_common(k)


def build_char_vocab(text: str):
    """按字典序建立词表,返回 char_to_id 与 id_to_char 双向映射。"""
    chars = sorted(set(text))
    char_to_id = {ch: i for i, ch in enumerate(chars)}
    id_to_char = {i: ch for ch, i in char_to_id.items()}
    return char_to_id, id_to_char


def to_char_ids(text: str, char_to_id: dict) -> list:
    """把字符串逐字符翻译成 id 列表。"""
    return [char_to_id[ch] for ch in text]


def main() -> None:
    """主流程:清洗 → 统计 → 建表 → 编码,并打印摘要。"""
    # 一条龙:清洗 → 建表 → 编码,顺便看一眼频次分布
    text = clean_text(CORPUS)
    char_to_id, id_to_char = build_char_vocab(text)
    # 交叉校验:频次之和应等于语料总字符数,确保统计没有漏掉任何字
    assert sum(char_stats(text).values()) == len(text)
    print(f"语料长度: {len(text)} 个字符")
    print(f"词表大小: {len(char_to_id)} 个字符")
    print("== 字符频次 TOP5 ==")
    for ch, cnt in freq_table(text, 5):
        print(f"  「{ch}」 x{cnt}")
    # 把清洗好的全文逐字转成 id,作为后续训练语料的雏形
    ids = to_char_ids(text, char_to_id)
    print(f"编码示例(前 8 个 id): {ids[:8]}")


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

把 s1 的 38 字符词表升级为「词表 + 合并规则」。BPE 的核心思想:反复统计相邻 token 对的出现次数,挑最高频的一对合并成一个新 token,循环 `num_merges` 次。本步要实现 `most_frequent_pair`(找最高频字对)、`merge_pair`(一趟扫描合并)与 `learn_bpe`(训练主循环)。

### 原理

GPT 的词表远不止 38 个字符——「明月」「故乡」这类高频词应当成为单个 token。BPE 就是逐轮贪心合并:第 1 轮统计发现「明」「月」相邻出现 4 次,是最高频字对,于是引入一个新 id 表示「明月」,把所有「明」「月」替换成它;第 2 轮在更新后的序列上继续统计,此时「床」「前」以 2 次胜出……新 token 的 id 从 `base = len(char_to_id)` 开始顺延,`pieces` 字典记录每个 id 拼出的文本,供打印规则与后续解码使用。合并必须用一趟左到右的扫描:同一轮内相邻的 `(left, right)` 全部替换,不能替换完再回头配对。

### 操作

1. 补全 `most_frequent_pair`:用 `Counter(zip(ids, ids[1:]))` 统计相邻对;序列为空时返回哨兵值 `((-1, -1), 0)`;
2. 补全 `learn_bpe` 循环体:调用 `merge_pair(ids, l, r, base + idx)` 做一趟合并,结果赋回 `ids`;
3. 运行 `main`,观察合并规则如何从「明」+「月」层层拼出「床前明月光,疑」,确认最终 token 数为 50。

### 常见坑

- 合并后 `l` 或 `r` 可能是合并产物,打印规则时必须查 `pieces` 而不是 `id_to_char`,否则直接 KeyError;
- `merge_pair` 必须一趟扫描内完成所有配对合并,用 `while` 指针推进,合并后 `i += 2` 跳过已合并的部分;
- 空序列或单元素序列的相邻对为空,`most_frequent_pair` 要返回哨兵值,否则 `main` 会崩。

