        self.script = script  # 引用共享:invoke 的 pop 直接消费调用方剧本

    def invoke(self, messages: list):
        if not self.script:
            raise RuntimeError("剧本已耗尽:调用次数与剧本对不上")
        return AIMessage(**self.script.pop(0))


script = [
    {"content": "", "tool_calls": [{"name": "search_knowledge", "args": {"query": "基础阶段丹"}, "id": "call_1"}]},
    {"content": "基础阶段丹要以九转灵草为引,文火炼足四十九日;配方详见资料。"},
    {"content": "", "tool_calls": [{"name": "search_knowledge", "args": {"query": "故障活动方案"}, "id": "call_2"}]},
    {"content": "上线验收活动方案在丹房二层,需避雷木作辅料,详情可查资料。"},
    {"content": "窗口里还剩最近 6 条消息,更早的已经压进摘要了。"},
    {"content": "最早那句「活动方案怎么制作?」已被压缩进摘要,我依然记得。"},
]

if MOCK:
    llm = ScriptedLLM(script)
else:
    llm = build_llm().bind_tools(build_pouch())

memory = ChatMemory(max_turns=3)


def run_turn(user_text: str) -> None:
    """一个带记忆的回合:入记忆 → 模型决策 → 执行工具 → 答复入记忆 → 压缩。"""
    memory.add("user", user_text)
    messages = list(memory.context())
    reply = llm.invoke(messages)
    if reply.tool_calls:
        messages.append(reply)
        for call in reply.tool_calls:
            text = dispatch(call["name"], call["args"])
            print(f"  ◆ {call['name']} -> {text}")
            messages.append(ToolMessage(content=text, tool_call_id=call["id"]))
        reply = llm.invoke(messages)
    print("任务调度台:", reply.content)
    memory.add("assistant", reply.content)


def main() -> None:
    for q in ["活动方案怎么制作?", "那故障活动方案在哪炼?", "现在窗口还剩几条?", "最早问的那句还记得吗?"]:
        print(f"\n—— 学习者问: {q}")
        run_turn(q)
    print("\n[检查] 剧本全部消耗:", not script)
    print("[检查] 摘要内容:", memory.summary)
    print("[检查] 摘要含最早提问:", "活动方案怎么制作?" in memory.summary)
    print("[检查] 窗口剩余:", len(memory.messages))
    # 剧本消费数量只在离线演示中可预测；真实模型的工具选择不是固定的。
    if MOCK:
        assert not script and "活动方案怎么制作?" in memory.summary
    else:
        assert memory.summary and len(memory.messages) <= memory.max_turns * 2


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

s2 只处理「一轮」:一次工具决策、一次结果回传。真实 Agent 的一个回合可能连环调用多次工具——比如查完基础阶段丹还要算成本、查故障还要查异常情况。本步把「模型决策 → 任务调度台执行 → 观察回传」收进 `AgentHarness.run` 的循环:循环内每步要么是终答(模型不再调工具,直接返回文本),要么是工具调用(执行、记录、回传后进入下一轮)。同时给循环加熔断:单回合最多 `max_steps` 步,防止模型陷入无限连环调工具。

### 原理

Harness 循环就是 ReAct 的落地:Reason(模型在回复里声明要调什么工具)、Act(我们调用 `dispatch` 真正执行)、Observe(把结果包成 `ToolMessage` 回喂模型)三件套轮转,直到模型给出不带 `tool_calls` 的终答。每一步我们都在自己这边记账:`step_count` 记总步数、`trace` 记每次工具调用(工具名 + 参数)——这是多轮 Agent 的可观测性基础,后续 s6 的行动报告就靠它。熔断是安全网:循环 `for _ in range(self.max_steps)` 步数用尽还没等到终答,就强制结束并返回「已达最大步数,转人工接管。」,避免工具链失控烧 token。

### 操作

1. 补全 `AgentHarness.run`:用户提问先入记忆,再从记忆取上下文;
2. 循环内先 `invoke` 拿 `decision`——没有 `tool_calls` 就是终答,入记忆并 `return`;
3. 有 `tool_calls` 则把决策追加进上下文,逐个 `dispatch`、记 `trace`、`ToolMessage` 回传,进入下一轮;
4. 循环外补上熔断:入记忆并返回转人工文案;设 `MOCK_LLM=1` 运行,第一问「一问一答」两步收场,第二问「连环五问」熔断收场。

### 常见坑

- 终答判定要用 `if not decision.tool_calls`,别用 `is None`——空列表同样是「不调工具」;
- 工具结果必须 `ToolMessage` 回传后再 `invoke`,否则模型看不到执行结果,下一轮只会重复同样的调用;
- 熔断文案要同时入记忆并作为返回值,不然报告与记忆对不上;
- `trace` 记的是「执行过什么」,`step_count` 记的是「走了几步」,两者数值不同很正常(一步可能调多个工具)。

