    for q in ["活动方案怎么制作?", "上线验收前要避开哪些故障难?"]:
        print(f"\n—— 学习者问: {q}")
        print("任务调度台:", harness.run(q))
    print("\n[检查] 剧本全部消耗:", not script)
    print("[检查] 总步数:", harness.step_count)
