    {"content": "", "tool_calls": [{"name": "search_knowledge", "args": {"query": "上线验收"}, "id": "call_5"}]},
    {"content": "", "tool_calls": [{"name": "search_knowledge", "args": {"query": "天故障"}, "id": "call_6"}]},
]

if MOCK:
