    if ok:
        return json.dumps({"ok": True, "data": data}, ensure_ascii=False)
    return json.dumps({"ok": False, "error": {"type": kind, "message": message}}, ensure_ascii=False)


def dispatch(name: str, args: dict) -> str:
    """执行工具并返回 JSON 信封:失败绝不抛出,都变成可读文本。"""
    spec = TOOLS.get(name)
    if spec is None:
        return _envelope(False, "unknown_tool", f"没有名为 {name} 的工具")
    missing = [k for k in spec["params"] if k not in args]
    if missing:
        return _envelope(False, "invalid_args", f"缺少参数: {missing}")
    try:
        return _envelope(True, data=spec["fn"](**args))
    except Exception as exc:  # noqa: BLE001
        return _envelope(False, "internal_error", f"{type(exc).__name__}: {exc}")


def build_pouch() -> list[StructuredTool]:
    """把注册表处理成 LangChain 工具,随 bind_tools 一起发给模型。"""
    return [
        StructuredTool.from_function(func=spec["fn"], name=name, description=spec["desc"])
        for name, spec in TOOLS.items()
    ]


def build_llm() -> ChatOpenAI:
    """装配 DeepSeek 客户端(OpenAI 兼容协议),配置全部来自环境变量。"""
    return ChatOpenAI(
        model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"),
        api_key=os.environ.get("OPENAI_API_KEY"),
        base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"),
        temperature=0,  # 工具调用要确定性,关掉随机性
    )


class ChatMemory:
    """短期记忆(压缩版):窗口只留最近 max_turns 轮,溢出即压进摘要。"""

    def __init__(self, max_turns: int = 2):
        self.max_turns = max_turns
        self.messages: list = []
        self.summary = ""

    def context(self) -> list:
        """记忆的对外窗口:system + 摘要 + 窗口内消息。"""
        ctx = [{"role": "system", "content": SYSTEM_PROMPT}]
        if self.summary:
            ctx.append({"role": "system", "content": f"[摘要] {self.summary}"})
        return ctx + self.messages

    def add(self, role: str, content: str) -> None:
        self.messages.append({"role": role, "content": content})
        self.compress()

    def compress(self) -> None:
        """窗口溢出时,把最旧的用户消息压进摘要,并丢弃整段旧对话。"""
        budget = self.max_turns * 2
        if len(self.messages) <= budget:
            return
        old = self.messages[:-budget]
        chunk = " ".join(m["content"] for m in old if m["role"] == "user")
        self.messages = self.messages[-budget:]
        if chunk:
            self.summary = f"已压缩对话:{chunk}(从略)"


class AgentHarness:
    """回合引擎:循环「决策 → 执行 → 观察」,收尾前压缩记忆。"""

    def __init__(self, llm, memory, max_steps: int = 5):
        self.llm = llm
        self.memory = memory
        self.max_steps = max_steps
        self.trace: list = []      # 工具调用记录:(工具名, 参数)
        self.step_count = 0        # 本回合已执行的总步数

    def run(self, user_text: str) -> str:
        """执行一个完整回合:每一步要么是终答,要么是工具调用。"""
        self.memory.add("user", user_text)
        messages = list(self.memory.context())
        for _ in range(self.max_steps):
            self.step_count += 1
            decision = self.llm.invoke(messages)
            if not decision.tool_calls:
                self.memory.add("assistant", decision.content)
                self.memory.compress()
                return decision.content
            messages.append(decision)
            for call in decision.tool_calls:
                result = dispatch(call["name"], call["args"])
                self.trace.append((call["name"], call["args"]))
                print(f"  ◆ {call['name']} -> {result}")
                messages.append(ToolMessage(content=result, tool_call_id=call["id"]))
        self.memory.add("assistant", "已达最大步数,转人工接管。")
        self.memory.compress()
        return "已达最大步数,转人工接管。"


class DujieAgent:
    """门面:对外只暴露 chat 与 action_report,依赖由构造器注入。"""

    def __init__(self, memory, harness):
        self.memory = memory
        self.harness = harness
        self.turn_count = 0

    def chat(self, user_text: str) -> str:
        """协作者发问:记轮次、走 Harness,返回终答。"""
        self.turn_count += 1
        print(f"\n—— 第 {self.turn_count} 轮: {user_text}")
        return self.harness.run(user_text)

    def action_report(self) -> str:
        """输出本次运行的可观测性汇总:轮次、工具调用、记忆规模。"""
        return "\n".join([
            "===== 任务调度台行动报告 =====",
            f"对话轮数: {self.turn_count}",
            f"工具调用: {len(self.harness.trace)} 次",
            f"记忆规模: {len(self.memory.messages)} 条最近消息 + 摘要 {len(self.memory.summary)} 字",
        ])


class ScriptedLLM:
    """离线剧本模型:invoke 时按顺序吐出剧本里的回复,无 Key 演示与测试用。"""

    def __init__(self, script: list):
        self.script = script  # 引用共享:invoke 的 pop 直接消费调用方剧本

    def invoke(self, messages: list):
        if not self.script:
            raise RuntimeError("剧本已耗尽:调用次数与剧本对不上")
        return AIMessage(**self.script.pop(0))


script = [
    # 第一问:一问一工具,2 次迭代出终答
    {"content": "", "tool_calls": [{"name": "search_knowledge", "args": {"query": "基础阶段丹"}, "id": "call_1"}]},
    {"content": "基础阶段丹以九转灵草为引,文火炼足四十九日,配方详见资料。"},
    # 第二问:成本计算工具,同样 2 次迭代
    {"content": "", "tool_calls": [{"name": "calc_forge_cost", "args": {"item_name": "展示素材", "quantity": 3, "unit_cost": 120, "rarity": "精品"}, "id": "call_2"}]},
    {"content": "三件精品展示素材共需 540 预算点,已在账房记下。"},
    # 第三问:纯闲聊,不调任何工具
    {"content": "那太好了,我们继续。"},
]

if MOCK:
    llm = ScriptedLLM(script)
else:
    llm = build_llm().bind_tools(build_pouch())

memory = ChatMemory(max_turns=2)
harness = AgentHarness(llm=llm, memory=memory, max_steps=5)
agent = DujieAgent(memory=memory, harness=harness)


def main() -> None:
    print("—— 任务调度台开张 ——")
    print("学习者: 活动方案怎么制作?")
    print("任务调度台:", agent.chat("活动方案怎么制作?"))
    print("学习者: 三件精品展示素材多少钱?")
    print("任务调度台:", agent.chat("三件精品展示素材多少钱?"))
    print("学习者: 好,我们继续。")
    print("任务调度台:", agent.chat("好,我们继续。"))
    print()
    print(agent.action_report())
    print("\n[检查] 剧本全部消耗:", not script)
    print("[检查] 摘要已生成:", bool(agent.memory.summary))
    print("[检查] 摘要内容:", agent.memory.summary)
    print("[检查] 窗口剩余:", len(agent.memory.messages))
    # 只有 MOCK 模式才存在固定 script；真实模型运行时验证可观察的状态契约。
    if MOCK:
        assert not script
        assert "活动方案怎么制作?" in agent.memory.summary
        assert len(agent.memory.messages) == 4  # max_turns=2 → 预算 4 条
    else:
        assert agent.turn_count == 3 and agent.memory.summary
    assert bool(agent.memory.summary)
    assert len(agent.memory.messages) <= agent.memory.max_turns * 2


if __name__ == "__main__":
    main()

steps.instruction:
### 目标

毕业设计的最后冲刺:把前几关打磨好的 Agent 应用,封装成一个能对外提供 HTTP 服务的 FastAPI 应用。本步先产出服务的完整源码 main.py,再用 Python 的 ast 模块做一次「源码审计」——在不安装 fastapi 的情况下,也能解析服务结构、盘点路由清单,为后续镜像封装打好地基。

### 原理

HTTP 服务的最小形态是三件套:路由(URL 到处理函数的映射)、请求模型(入参契约)、应用对象(FastAPI 实例)。我们把这段代码当作「文本」来生产与审计:ast.parse 把源码文本变成语法树,ast.walk 深度遍历每个节点;带路由装饰器的函数节点,其 decorator_list 里躺着形如 app.get 的 ast.Call 节点,它的 func.attr 是 HTTP 方法,args[0].value 是路径。这样解析,不需要 fastapi 真正被 import——语法结构是纯文本事实,审计因此又快又稳。

### 操作

1. 通读已给出的 SERVICE_PY:确认 /health 与 /api/chat 两条路由、ChatRequest 请求模型与 uvicorn 启动入口;
2. 补全 audit_service:用 ast.walk 遍历语法树,只关注函数节点;
3. 在函数节点的 decorator_list 里识别路由装饰器:是 ast.Call 且 func 是 ast.Attribute 才算;
4. 取方法名(func.attr)与路径(第一个位置参数),组装成路由字典并追加到 routes;
5. 运行 main():应看到 GET /health 与 POST /api/chat 两条路由被盘点出来。

### 常见坑

- 装饰器也可能是 ast.Name(普通装饰器),必须同时校验 ast.Call 与 ast.Attribute,否则会把普通装饰器误认成路由;
- dec.args 为空时(装饰器没有位置参数)要兜底用问号,否则 IndexError 会直接炸掉审计;
- 先写文本、后审计的顺序别颠倒:审计永远发生在「代码尚未被执行」时,这正是把校验前置到部署前的底气。

steps.solutionCode:
"""终期交付 · s1:FastAPI 服务封装
把前几关打磨好的 Agent 应用封装为 HTTP 服务:先写出 main.py 的完整源码,
再用 ast 做「源码审计」——不依赖 fastapi 也能解析结构、盘点路由。
"""
import ast

# 目标服务 main.py 的完整源码(文本)。真实项目里,这一步就是把文件真实写出。
SERVICE_PY = """# 黑糖资料室 · Agent 应用 HTTP 服务(由构建脚本生成)。
import os

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="黑糖资料室", version="0.1.0")

@app.get("/health")
def health() -> dict:
    # 存活探针:进程在,服务在。
    return {"status": "ok", "service": "dujie-feisheng",
            "model": os.getenv("MODEL_NAME", "deepseek-v4-pro")}

class ChatRequest(BaseModel):
    message: str
    session_id: str = "default"

@app.post("/api/chat")
def chat(req: ChatRequest) -> dict:
    if not req.message.strip():
        raise HTTPException(status_code=400, detail="消息不能为空")
    return {"session_id": req.session_id, "reply": f"[演示] 收到:{req.message[:20]}"}

if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
"""


def write_service(path: str) -> str:
    """把服务源码写到磁盘,返回路径。"""
    with open(path, "w", encoding="utf-8") as f:
        f.write(SERVICE_PY)
    return path


def audit_service(source: str) -> list[dict]:
    """用 ast 解析服务源码,盘点每条路由:方法、路径、处理函数。"""
    tree = ast.parse(source)
    routes = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for dec in node.decorator_list:
            if not isinstance(dec, ast.Call) or not isinstance(dec.func, ast.Attribute):
                continue
            method = dec.func.attr
            if not method.startswith(("get", "post", "put", "delete")):
                continue
            path = dec.args[0].value if dec.args else "?"
            routes.append({"method": method.upper(), "path": path, "func": node.name})
    return routes


def main() -> None:
    path = write_service("main.py")
    routes = audit_service(SERVICE_PY)
    print(f"== 服务源码审计 {path} ==")
    print(f"  源码 {len(SERVICE_PY.splitlines())} 行,AST 顶层节点 {len(ast.parse(SERVICE_PY).body)} 个")
    for r in routes:
        print(f"  {r['method']:<6} {r['path']:<12} -> {r['func']}")
    if routes:
        print(f"  共发现 {len(routes)} 条路由,结构合格,可以进入镜像封装。")
    else:
        print("  [警告] 一条路由都没有,这样的服务上线等于没上线!")


if __name__ == "__main__":
    main()

